import React from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import App from "./App.jsx";
import "./styles/main.css";
import { CssBaseline, ThemeProvider } from "@mui/material";
import MyTheme from "./theme";

const root = createRoot(document.getElementById("root"));

root.render(
  <React.StrictMode>
    <BrowserRouter
      future={{
        v7_startTransition: true,
        v7_relativeSplatPath: true,
      }}
    >
      <ThemeProvider theme={MyTheme}>
        <CssBaseline />
        <App />
      </ThemeProvider>
    </BrowserRouter>
  </React.StrictMode>
);
APP LAYOUT
import {
  AccountCircleRounded, DashboardRounded, DescriptionRounded, HealthAndSafetyRounded, LogoutRounded,
  MenuRounded, PaymentsRounded, PersonRounded, PlaylistAddCheckRounded
} from "@mui/icons-material";
import {
  AppBar,
  Avatar,
  Box,
  Divider,
  Drawer,
  IconButton,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
  Toolbar,
  Typography,
} from "@mui/material";
import { useState } from "react";
import { NavLink, Outlet, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const drawerWidth = 270;

const managerLinks = [
  { label: "Dashboard", path: "/dashboard", icon: <DashboardRounded /> },
  { label: "Payment Preview", path: "/payments/preview", icon: <PlaylistAddCheckRounded /> },
  { label: "Payment Batches", path: "/payments", icon: <PaymentsRounded /> },
  { label: "Payslips", path: "/payslips", icon: <DescriptionRounded /> },
  { label: "Profile", path: "/profile", icon: <AccountCircleRounded /> },
];

const employeeLinks = [
  { label: "My Payslips", path: "/payslips", icon: <DescriptionRounded /> },
  { label: "Profile", path: "/profile", icon: <AccountCircleRounded /> },
];

function Sidebar({ onNavigate }) {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const links = user.role === "manager" ? managerLinks : employeeLinks;
  const logout = async () => {
    await signOut();
    onNavigate?.();
    navigate("/login", { replace: true });
  };

  return <Box className="sidebar-content">
    <Box className="brand-lockup">
      <Box className="brand-mark" aria-hidden="true"><HealthAndSafetyRounded /></Box>
      <Box><Typography className="brand-name">Emergencies</Typography>
        <Typography className="brand-subtitle">First Aid &amp; Rescue</Typography></Box>
    </Box><Divider className="sidebar-divider" />
    <Typography className="sidebar-section-label">Payroll workspace</Typography>
    <List component="nav" aria-label="Primary navigation" sx={{ px: 1.5 }}>
      {links.map((link) => {
        const isActive =
          link.path === "/payments"
            ? location.pathname === "/payments" ||
            (location.pathname.startsWith("/payments/") &&
              location.pathname !== "/payments/preview")
            : location.pathname === link.path;

        return (
          <ListItemButton
            key={link.path}
            component={NavLink}
            to={link.path}
            onClick={onNavigate}
            className={
              isActive
                ? "sidebar-link sidebar-link-active"
                : "sidebar-link"
            }
          >
            <ListItemIcon>{link.icon}</ListItemIcon>
            <ListItemText primary={link.label} />
          </ListItemButton>
        );
      })}</List>
    <Box sx={{ mt: "auto", px: 1.5 }}>
      <ListItemButton className="sidebar-link" onClick={logout}>
        <ListItemIcon>
          <LogoutRounded />
        </ListItemIcon><ListItemText primary="Logout" />
      </ListItemButton></Box><Box className="sidebar-security-note">
      <HealthAndSafetyRounded fontSize="small" />
      <Typography variant="caption">Secure payroll access</Typography>
    </Box>
  </Box>;
}

function TopBar({ onMenuClick }) {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const [anchor, setAnchor] = useState(null);
  const handleLogout = async () => {
    setAnchor(null);
    await signOut();
    navigate("/login", { replace: true });
  };
  const initials = user?.fullName?.split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase() || "U";

  return (
    <AppBar position="fixed" color="inherit" elevation={0} className="app-topbar">
      <Toolbar>
        <IconButton className="mobile-menu-button" edge="start" onClick={onMenuClick} aria-label="Open navigation"><MenuRounded /></IconButton>
        <Box sx={{ flexGrow: 1 }}><Typography variant="h3" component="h1">Payroll Automation</Typography><Typography variant="caption" color="text.secondary">Secure payment operations</Typography></Box>
        <IconButton onClick={(event) => setAnchor(event.currentTarget)} aria-label="Open profile menu" aria-haspopup="menu"><Avatar sx={{ width: 38, height: 38, bgcolor: "primary.main", fontSize: 15 }}>{initials}</Avatar></IconButton>
        <Box className="topbar-user-copy"><Typography variant="body2" fontWeight={700}>{user?.fullName}</Typography><Typography variant="caption" color="text.secondary" sx={{ textTransform: "capitalize" }}>{user?.role}</Typography></Box>
        <Menu anchorEl={anchor} open={Boolean(anchor)} onClose={() => setAnchor(null)}>
          <MenuItem disabled><PersonRounded fontSize="small" sx={{ mr: 1 }} />{user?.email}</MenuItem><Divider /><MenuItem onClick={handleLogout}><LogoutRounded fontSize="small" sx={{ mr: 1 }} />Log out</MenuItem>
        </Menu>
      </Toolbar>
    </AppBar>
  );
}

export default function AppLayout() {
  const [mobileOpen, setMobileOpen] = useState(false);
  return (
    <Box className="application-shell">
      <TopBar onMenuClick={() => setMobileOpen(true)} />
      <Box component="nav" aria-label="Application navigation">
        <Drawer variant="temporary" open={mobileOpen} onClose={() => setMobileOpen(false)} ModalProps={{ keepMounted: true }} sx={{ display: { xs: "block", md: "none" }, "& .MuiDrawer-paper": { width: drawerWidth } }}><Sidebar onNavigate={() => setMobileOpen(false)} /></Drawer>
        <Drawer variant="permanent" open sx={{ display: { xs: "none", md: "block" }, "& .MuiDrawer-paper": { width: drawerWidth } }}><Sidebar /></Drawer>
      </Box>
      <Box component="main" className="application-main"><Outlet /></Box>
    </Box>
  );
}
PAYMENT COMPONENTS
import { yupResolver } from "@hookform/resolvers/yup";
import { DownloadRounded, OpenInNewRounded, VisibilityRounded } from "@mui/icons-material";
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import { useEffect } from "react";
import { Controller, useForm } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import * as yup from "yup";
import { formatCurrency, formatDate, formatDateTime, formatPeriod } from "../utils";
import { ConfirmDialog, StatusChip } from "./CommonComponents";

const bankDetailsSchema = yup.object({
  bankCode: yup.string().trim().matches(/^[A-Za-z0-9-]{3,20}$/, "Use 3-20 letters, numbers, or hyphens").required("Bank code is required"),
  bankAccountNumber: yup.string().trim().matches(/^[A-Za-z0-9-]{5,50}$/, "Use 5-50 letters, numbers, or hyphens").required("Bank account number is required"),
});

function BankDetailsDialog({ employee, open, onClose, onSave, loading, serverError }) {
  const { control, handleSubmit, reset, formState: { errors } } = useForm({ resolver: yupResolver(bankDetailsSchema), defaultValues: { bankCode: "", bankAccountNumber: "" } });
  useEffect(() => { if (open) reset({ bankCode: "", bankAccountNumber: "" }); }, [open, reset]);
  return <Dialog open={open} onClose={loading ? undefined : onClose} fullWidth maxWidth="sm"><DialogTitle>Update bank details</DialogTitle><DialogContent>
    <Alert severity="info" sx={{ mb: 2 }}>Updating {employee?.employeeName} ({employee?.employeeReference}). Existing full account details are never displayed.</Alert>
    {serverError && <Alert severity="error" sx={{ mb: 1 }}>{serverError}</Alert>}
    <Controller name="bankCode" control={control} render={({ field }) => <TextField {...field} label="Bank code" fullWidth margin="normal" error={Boolean(errors.bankCode)} helperText={errors.bankCode?.message} autoComplete="off" />} />
    <Controller name="bankAccountNumber" control={control} render={({ field }) => <TextField {...field} label="Bank account number" fullWidth margin="normal" error={Boolean(errors.bankAccountNumber)} helperText={errors.bankAccountNumber?.message} autoComplete="off" />} />
  </DialogContent><DialogActions sx={{ p: 2.5 }}><Button color="inherit" onClick={onClose} disabled={loading}>Cancel</Button><Button variant="contained" onClick={handleSubmit(onSave)} disabled={loading} startIcon={loading ? <CircularProgress size={17} color="inherit" /> : null}>Save securely</Button></DialogActions></Dialog>;
}

function GeneratePaymentDialog({ open, preview, onClose, onConfirm, loading }) {
  if (!preview) return null;
  return <ConfirmDialog open={open} title="Generate payment batch" confirmLabel="Generate and sync" onClose={onClose} onConfirm={onConfirm} loading={loading}>
    <Alert severity="warning" sx={{ mb: 2 }}>This creates permanent payment records and starts HRMS synchronisation using approved values.</Alert>
    <Box className="dialog-summary-grid"><Typography color="text.secondary">Pay period</Typography><Typography fontWeight={700}>{formatPeriod(preview.payPeriod.startDate, preview.payPeriod.endDate)}</Typography><Typography color="text.secondary">Employees</Typography><Typography fontWeight={700}>{preview.employeeCount}</Typography><Typography color="text.secondary">Total payment</Typography><Typography fontWeight={700}>{formatCurrency(preview.totalAmount)}</Typography></Box>
  </ConfirmDialog>;
}

function PaymentBatchItemsTable({ items }) {
  return <TableContainer><Table size="small"><TableHead><TableRow><TableCell>Employee</TableCell><TableCell>Bank</TableCell><TableCell align="right">Gross</TableCell><TableCell align="right">Incentive</TableCell><TableCell align="right">CPF</TableCell><TableCell align="right">SDL</TableCell><TableCell align="right">Net pay</TableCell><TableCell>Payment reference</TableCell></TableRow></TableHead><TableBody>{items.map((item) => <TableRow key={item.id} hover><TableCell><strong>{item.employeeName}</strong><br /><small>{item.employeeReference}</small></TableCell><TableCell>{item.bankCode}<br /><small>{item.bankAccountNumber}</small></TableCell><TableCell align="right">{formatCurrency(item.grossPay)}</TableCell><TableCell align="right">{formatCurrency(item.incentivePay)}</TableCell><TableCell align="right">{formatCurrency(item.cpfAmount)}</TableCell><TableCell align="right">{formatCurrency(item.sdlAmount)}</TableCell><TableCell align="right"><strong>{formatCurrency(item.netPay)}</strong></TableCell><TableCell>{item.paymentReference}</TableCell></TableRow>)}</TableBody></Table></TableContainer>;
}

function PaymentBatchTable({ rows, onDownload, downloadingId }) {
  const navigate = useNavigate();
  return <TableContainer><Table size="small"><TableHead><TableRow><TableCell>Batch reference</TableCell><TableCell>Pay period ID</TableCell><TableCell>Status</TableCell><TableCell>HRMS</TableCell><TableCell align="right">Employees</TableCell><TableCell align="right">Total</TableCell><TableCell>Generated</TableCell><TableCell align="right">Actions</TableCell></TableRow></TableHead><TableBody>{rows.map((batch) => <TableRow hover key={batch.id}><TableCell sx={{ fontWeight: 700 }}>{batch.batchReference}</TableCell><TableCell><span className="mono-id">{batch.payPeriodId}</span></TableCell><TableCell><StatusChip status={batch.status} /></TableCell><TableCell><StatusChip status={batch.hrmsSyncStatus} /></TableCell><TableCell align="right">{batch.employeeCount}</TableCell><TableCell align="right">{formatCurrency(batch.totalAmount)}</TableCell><TableCell>{formatDateTime(batch.generatedAt)}</TableCell><TableCell align="right"><Tooltip title="View details"><IconButton aria-label={`View ${batch.batchReference}`} onClick={() => navigate(`/payments/${batch.id}`)}><OpenInNewRounded /></IconButton></Tooltip>{batch.status !== "cancelled" && <Tooltip title="Download CSV"><span><IconButton aria-label={`Download ${batch.batchReference} CSV`} disabled={downloadingId === batch.id} onClick={() => onDownload(batch)}><DownloadRounded /></IconButton></span></Tooltip>}</TableCell></TableRow>)}</TableBody></Table></TableContainer>;
}

function PayslipTable({ rows, onDownload, downloadingId }) {
  const navigate = useNavigate();
  return <TableContainer><Table size="small"><TableHead><TableRow><TableCell>Employee</TableCell><TableCell>Payslip reference</TableCell><TableCell>Pay period</TableCell><TableCell align="right">Gross</TableCell><TableCell align="right">Incentive</TableCell><TableCell align="right">CPF</TableCell><TableCell align="right">SDL</TableCell><TableCell align="right">Other deduction</TableCell><TableCell align="right">Net pay</TableCell><TableCell>Generated</TableCell><TableCell align="right">Actions</TableCell></TableRow></TableHead><TableBody>{rows.map((payslip) => <TableRow key={payslip.id} hover><TableCell><strong>{payslip.employeeName}</strong><br /><small>{payslip.employeeReference}</small></TableCell><TableCell>{payslip.payslipReference}</TableCell><TableCell>{formatPeriod(payslip.payPeriodStart, payslip.payPeriodEnd)}</TableCell><TableCell align="right">{formatCurrency(payslip.grossPay)}</TableCell><TableCell align="right">{formatCurrency(payslip.incentivePay)}</TableCell><TableCell align="right">{formatCurrency(payslip.cpfAmount)}</TableCell><TableCell align="right">{formatCurrency(payslip.sdlAmount)}</TableCell><TableCell align="right">{formatCurrency(payslip.otherDeduction)}</TableCell><TableCell align="right"><strong>{formatCurrency(payslip.netPay)}</strong></TableCell><TableCell>{formatDate(payslip.generatedAt)}</TableCell><TableCell align="right"><Tooltip title="View payslip"><IconButton aria-label={`View ${payslip.payslipReference}`} onClick={() => navigate(`/payslips/${payslip.id}`)}><VisibilityRounded /></IconButton></Tooltip><Tooltip title="Download PDF"><span><IconButton aria-label={`Download ${payslip.payslipReference} PDF`} disabled={downloadingId === payslip.id} onClick={() => onDownload(payslip)}>{downloadingId === payslip.id ? <CircularProgress size={20} /> : <DownloadRounded />}</IconButton></span></Tooltip></TableCell></TableRow>)}</TableBody></Table></TableContainer>;
}

export { BankDetailsDialog, GeneratePaymentDialog, PaymentBatchItemsTable, PaymentBatchTable, PayslipTable };
