+"use strict";
+
+const MANAGER_ID = "81000000-0000-0000-0000-000000000002";
+const COMPANY_NAME = process.env.COMPANY_NAME || "Emergencies First Aid & Rescue";
+const STAFF_COUNT = 100;
+
+const uuid = (prefix, number) =>
+    `${prefix}000000-0000-4000-8000-${String(number).padStart(12, "0")}`;
+
+const staffId = (number) => uuid("90", number);
+const periodId = (number) => uuid("91", number);
+const payrollLineId = (periodNumber, employeeNumber) =>
+    uuid("92", periodNumber * 1000 + employeeNumber);
+const batchId = (number) => uuid("93", number);
+const batchItemId = (batchNumber, employeeNumber) =>
+    uuid("94", batchNumber * 1000 + employeeNumber);
+const payslipId = (batchNumber, employeeNumber) =>
+    uuid("95", batchNumber * 1000 + employeeNumber);
+const approvalId = (periodNumber) => uuid("96", periodNumber);
+
+const now = new Date("2026-07-26T08:00:00.000Z");
+const timestamp = (daysAgo = 0, hours = 0) =>
+    new Date(now.getTime() - daysAgo * 86400000 + hours * 3600000);
+
+const names = [
+    "Tan Wei Ming", "Nurul Aisyah", "Rajesh Kumar", "Lim Jia Hui",
+    "Muhammad Irfan", "Chloe Lee", "Arjun Nair", "Siti Hajar",
+    "Marcus Goh", "Priya Sharma", "Ethan Wong", "Farah Ahmad",
+    "Daniel Teo", "Mei Lin", "Hafiz Rahman", "Ananya Rao",
+    "Joshua Ong", "Alicia Tan", "Vikram Singh", "Nadia Ismail",
+];
+
+const scenarios = [
+    { number: 1, key: "READY-LARGE", start: "2026-07-01", end: "2026-07-15", status: "approved", locked: true, employees: 100, approved: true },
+    { number: 2, key: "MISSING-BANK", start: "2026-06-16", end: "2026-06-30", status: "approved", locked: true, employees: 3, approved: true, staffNumbers: [98, 99, 100] },
+    { number: 3, key: "INCOMPLETE", start: "2026-06-01", end: "2026-06-15", status: "approved", locked: true, employees: 3, approved: true, incomplete: true },
+    { number: 4, key: "ZERO-NET", start: "2026-05-16", end: "2026-05-31", status: "approved", locked: true, employees: 2, approved: true, zeroNet: true },
+    { number: 5, key: "EMPTY", start: "2026-05-01", end: "2026-05-15", status: "approved", locked: true, employees: 0, approved: true },
+    { number: 6, key: "GENERATED", start: "2026-04-16", end: "2026-04-30", status: "approved", locked: true, employees: 10, approved: true, batchStatus: "generated", hrmsStatus: "not_started" },
+    { number: 7, key: "COMPLETED-LARGE", start: "2026-04-01", end: "2026-04-15", status: "payment_ready", locked: true, employees: 100, approved: true, batchStatus: "completed", hrmsStatus: "completed", payslips: true },
+    { number: 8, key: "CANCELLED", start: "2026-03-16", end: "2026-03-31", status: "approved", locked: true, employees: 10, approved: true, batchStatus: "cancelled", hrmsStatus: "not_started" },
+    { number: 9, key: "HRMS-FAILED", start: "2026-03-01", end: "2026-03-15", status: "approved", locked: true, employees: 10, approved: true, batchStatus: "hrms_sync_failed", hrmsStatus: "failed" },
+    { number: 10, key: "PENDING-SYNC", start: "2026-02-16", end: "2026-02-28", status: "approved", locked: true, employees: 10, approved: true, batchStatus: "hrms_sync_pending", hrmsStatus: "pending" },
+    { number: 11, key: "GENERATING", start: "2026-02-01", end: "2026-02-15", status: "approved", locked: true, employees: 10, approved: true, batchStatus: "generating", hrmsStatus: "not_started" },
+    { number: 12, key: "PENDING-APPROVAL", start: "2026-01-16", end: "2026-01-31", status: "pending_approval", locked: false, employees: 5 },
+    { number: 13, key: "DRAFT-EMPTY", start: "2026-01-01", end: "2026-01-15", status: "draft", locked: false, employees: 0 },
+    { number: 14, key: "VALIDATED", start: "2025-12-16", end: "2025-12-31", status: "validated", locked: false, employees: 5 },
+    { number: 15, key: "APPROVED-UNLOCKED", start: "2025-12-01", end: "2025-12-15", status: "approved", locked: false, employees: 5, approved: true },
+    { number: 16, key: "APPROVAL-MISSING", start: "2025-11-16", end: "2025-11-30", status: "approved", locked: true, employees: 5 },
+];
+
+const archiveScenarios = Array.from({ length: 30 }, (_, index) => {
+    const number = 20 + index;
+    const end = new Date(Date.UTC(2025, 10, 15) - index * 16 * 86400000);
+    const start = new Date(end.getTime() - 14 * 86400000);
+    return {
+        number,
+        key: `ARCHIVE-${String(index + 1).padStart(2, "0")}`,
+        start: start.toISOString().slice(0, 10),
+        end: end.toISOString().slice(0, 10),
+        status: "payment_ready",
+        locked: true,
+        employees: 1,
+        approved: true,
+        batchStatus: "completed",
+        hrmsStatus: "completed",
+        payslips: true,
+        staffNumbers: [(index % STAFF_COUNT) + 1],
+    };
+});
+
