    const cpf = Math.round(gross * 0.1 * 100) / 100;
    const sdl = Math.min(11.25, Math.max(2, Math.round(gross * 0.0025 * 100) / 100));
    const net = options.zeroNet ? 0 : Math.round((gross + incentive - cpf - sdl) * 100) / 100;
    return { gross, incentive, cpf, sdl, net };
};

