    ["Rajesh Kumar", "part_time", "DBS", "6510000003"],
    ["Lim Jia Hui", "full_time", "OCBC", "6510000004"],
    ["Muhammad Irfan", "part_time", "UOB", "6510000005"],
    ["Chloe Lee", "part_time", null, "6510000006"],
    ["Arjun Nair", "full_time", "DBS", null],
