const scenarios = [
    {
        number: 1,
        key: "READY",
        start: "2026-07-01",
        end: "2026-07-15",
        status: "approved",
        locked: true,
        staffNumbers: [1, 2, 3, 4, 5],
        approved: true,
    },
    {
        number: 2,
        key: "MISSING-BANK",
        start: "2026-06-16",
        end: "2026-06-30",
        status: "approved",
        locked: true,
        staffNumbers: [6, 7],
        approved: true,
    },
    {
        number: 3,
        key: "HRMS-FAILED",
        start: "2026-06-01",
        end: "2026-06-15",
        status: "approved",
        locked: true,
        staffNumbers: [1, 2, 3],
        approved: true,
