        staffNumbers: [1, 2, 3],
        approved: true,
        batchStatus: "generated",
        hrmsStatus: "not_started",
    },
];

const payrollAmounts = (employeeNumber) => {
    const gross = 1500 + employeeNumber * 125;
    const incentive = employeeNumber % 2 === 0 ? 100 : 50;
    const cpf = Math.round(gross * 0.1 * 100) / 100;
    const sdl = Math.min(11.25, Math.max(2, Math.round(gross * 0.0025 * 100) / 100));
    const net = Math.round((gross + incentive - cpf - sdl) * 100) / 100;
    return { gross, incentive, cpf, sdl, net };
};

const upsertRows = async (queryInterface, table, rows, updateColumns, transaction) => {
    if (!rows.length) return;
    await queryInterface.bulkInsert(table, rows, {
        transaction,
        updateOnDuplicate: updateColumns,
        upsertKeys: ["id"],
    });
};

const buildPayPeriods = () => scenarios.map((scenario) => {
    const totals = scenario.staffNumbers.reduce((result, employeeNumber) => {
        const amounts = payrollAmounts(employeeNumber);
        return { gross: result.gross + amounts.gross, net: result.net + amounts.net };
    }, { gross: 0, net: 0 });
    return {
        id: periodId(scenario.number),
        start_date: scenario.start,
        end_date: scenario.end,
        status: scenario.status,
        validated_at: timestamp(90 - scenario.number),
        total_gross: totals.gross.toFixed(2),
        total_net: totals.net.toFixed(2),
        is_locked: scenario.locked,
        locked_at: scenario.locked ? timestamp(85 - scenario.number) : null,
        created_at: timestamp(100 - scenario.number),
        updated_at: now,
    };
});

const buildApprovals = () => scenarios.filter((scenario) => scenario.approved).map((scenario) => ({
    id: approvalId(scenario.number),
    pay_period_id: periodId(scenario.number),
    decision: "approved",
    approved_by: "Development Test Payroll Manager",
    comment: `UC-005 test approval for ${scenario.key}.`,
    decided_at: timestamp(80 - scenario.number),
    created_at: timestamp(80 - scenario.number),
}));

const buildPayrollLines = () => scenarios.flatMap((scenario) =>
    scenario.staffNumbers.map((employeeNumber) => {
        const amounts = payrollAmounts(employeeNumber);
        return {
            id: payrollLineId(scenario.number, employeeNumber),
            pay_period_id: periodId(scenario.number),
            staff_id: staffId(employeeNumber),
            gross_pay: amounts.gross.toFixed(2),
            incentive_pay: amounts.incentive.toFixed(2),
            cpf_amount: amounts.cpf.toFixed(2),
            sdl_amount: amounts.sdl.toFixed(2),
            net_pay: amounts.net.toFixed(2),
            status: "ok",
            created_at: timestamp(75 - scenario.number),
            updated_at: now,
        };
    }));

const batchReference = (scenario) => `DEV-PAY-${scenario.key}`;

const buildBatches = () => scenarios.filter((scenario) => scenario.batchStatus).map((scenario) => {
    const total = scenario.staffNumbers.reduce((sum, employeeNumber) =>
        sum + payrollAmounts(employeeNumber).net, 0);
    const generatedAt = timestamp(70 - scenario.number);
    return {
        id: batchId(scenario.number),
        pay_period_id: periodId(scenario.number),
        batch_reference: batchReference(scenario),
        file_format: "giro",
        employee_count: scenario.staffNumbers.length,
        total_amount: total.toFixed(2),
        status: scenario.batchStatus,
        hrms_sync_status: scenario.hrmsStatus,
        hrms_reference: scenario.batchStatus === "completed" ? "HRMS-DEV-UC005-COMPLETED" : null,
        hrms_error_message: scenario.batchStatus === "hrms_sync_failed"
            ? "Mock HRMS synchronisation failed for UC-005 retry testing."
            : null,
        generated_by: MANAGER_ID,
        generated_at: generatedAt,
        hrms_synced_at: scenario.batchStatus === "completed"
            ? new Date(generatedAt.getTime() + 60000)
            : null,
        cancelled_by: scenario.batchStatus === "cancelled" ? MANAGER_ID : null,
        cancelled_at: scenario.batchStatus === "cancelled"
            ? new Date(generatedAt.getTime() + 120000)
            : null,
        cancellation_reason: scenario.batchStatus === "cancelled"
            ? "Cancelled UC-005 development test batch."
            : null,
        created_at: generatedAt,
        updated_at: now,
    };
});

const staffByNumber = new Map(staff.map((employee, index) => [index + 1, employee]));

const buildBatchItems = () => scenarios.filter((scenario) => scenario.batchStatus).flatMap((scenario) =>
    scenario.staffNumbers.map((employeeNumber) => {
        const employee = staffByNumber.get(employeeNumber);
        const amounts = payrollAmounts(employeeNumber);
        return {
            id: batchItemId(scenario.number, employeeNumber),
            payment_batch_id: batchId(scenario.number),
            payroll_line_id: payrollLineId(scenario.number, employeeNumber),
            staff_id: staffId(employeeNumber),
            employee_reference: employee.external_ref,
            employee_name: employee.full_name,
            bank_code: employee.bank_code,
            bank_account_no: employee.bank_account_no,
            gross_pay: amounts.gross.toFixed(2),
            incentive_pay: amounts.incentive.toFixed(2),
            cpf_amount: amounts.cpf.toFixed(2),
            sdl_amount: amounts.sdl.toFixed(2),
            other_deduction: "0.00",
            net_pay: amounts.net.toFixed(2),
            payment_reference: `${batchReference(scenario)}-${employee.external_ref}`,
            created_at: timestamp(70 - scenario.number),
            updated_at: now,
        };
    }));

const buildPayslips = () => scenarios.filter((scenario) => scenario.payslips).flatMap((scenario) =>
    scenario.staffNumbers.map((employeeNumber) => {
        const employee = staffByNumber.get(employeeNumber);
        const amounts = payrollAmounts(employeeNumber);
        return {
            id: payslipId(scenario.number, employeeNumber),
            payment_batch_id: batchId(scenario.number),
            payroll_line_id: payrollLineId(scenario.number, employeeNumber),
            staff_id: staffId(employeeNumber),
            payslip_reference: `PS-${batchReference(scenario)}-${String(employeeNumber).padStart(3, "0")}`,
            company_name: COMPANY_NAME,
            employee_reference: employee.external_ref,
            employee_name: employee.full_name,
            pay_period_start: scenario.start,
            pay_period_end: scenario.end,
            gross_pay: amounts.gross.toFixed(2),
            incentive_pay: amounts.incentive.toFixed(2),
            cpf_amount: amounts.cpf.toFixed(2),
            sdl_amount: amounts.sdl.toFixed(2),
            other_deduction: "0.00",
            net_pay: amounts.net.toFixed(2),
            batch_reference: batchReference(scenario),
            generated_at: timestamp(69 - scenario.number),
            created_at: timestamp(69 - scenario.number),
            updated_at: now,
        };
    }));

const assertDevelopment = () => {
    if (process.env.NODE_ENV === "production") {
        throw new Error("Development payment test data must not be seeded in production.");
    }
};

const legacyStaffIds = Array.from(
    { length: LEGACY_STAFF_COUNT },
    (_, index) => staffId(index + 1),
);
const legacyPeriodIds = Array.from(
    { length: LEGACY_PERIOD_COUNT },
    (_, index) => periodId(index + 1),
);

const removeOwnedData = async (queryInterface, transaction) => {
    const [ownedBatches] = await queryInterface.sequelize.query(
        `SELECT id FROM payment_batch
         WHERE batch_reference LIKE 'DEV-PAY-%'
            OR pay_period_id IN (:periodIds)`,
        { replacements: { periodIds: legacyPeriodIds }, transaction },
    );
    const ownedBatchIds = ownedBatches.map((batch) => batch.id);

    if (ownedBatchIds.length) {
        await queryInterface.bulkDelete("payslip", {
            payment_batch_id: { [Op.in]: ownedBatchIds },
        }, { transaction });
        await queryInterface.bulkDelete("payment_batch_item", {
            payment_batch_id: { [Op.in]: ownedBatchIds },
        }, { transaction });
        await queryInterface.bulkDelete("payment_batch", {
            id: { [Op.in]: ownedBatchIds },
        }, { transaction });
    }
    await queryInterface.bulkDelete("approval", {
        pay_period_id: { [Op.in]: legacyPeriodIds },
    }, { transaction });
    await queryInterface.bulkDelete("payroll_line", {
        pay_period_id: { [Op.in]: legacyPeriodIds },
    }, { transaction });
    await queryInterface.bulkDelete("pay_period", {
        id: { [Op.in]: legacyPeriodIds },
    }, { transaction });
    await queryInterface.bulkDelete("user_account", {
        id: LEGACY_TEST_EMPLOYEE_USER_ID,
    }, { transaction });
    await queryInterface.bulkDelete("staff", {
        id: { [Op.in]: legacyStaffIds },
    }, { transaction });
};

module.exports = {
    async up(queryInterface) {
        assertDevelopment();
        const transaction = await queryInterface.sequelize.transaction();
        try {
            const manager = await queryInterface.rawSelect("user_account", {
                where: { id: MANAGER_ID },
                transaction,
            }, "id");
            if (!manager) {
                throw new Error("Seed the existing authentication manager before the UC-005 payment data.");
            }

            await removeOwnedData(queryInterface, transaction);
            await upsertRows(queryInterface, "staff", staff, [
                "external_ref", "full_name", "employment_type", "bank_account_no",
                "bank_code", "cpf_eligible", "status", "updated_at",
            ], transaction);
            await upsertRows(queryInterface, "pay_period", buildPayPeriods(), [
                "start_date", "end_date", "status", "validated_at", "total_gross",
                "total_net", "is_locked", "locked_at", "updated_at",
            ], transaction);
            await upsertRows(queryInterface, "approval", buildApprovals(), [
                "pay_period_id", "decision", "approved_by", "comment", "decided_at",
            ], transaction);
            await upsertRows(queryInterface, "payroll_line", buildPayrollLines(), [
                "pay_period_id", "staff_id", "gross_pay", "incentive_pay",
                "cpf_amount", "sdl_amount", "net_pay", "status", "updated_at",
            ], transaction);
            await upsertRows(queryInterface, "payment_batch", buildBatches(), [
                "pay_period_id", "batch_reference", "file_format", "employee_count",
                "total_amount", "status", "hrms_sync_status", "hrms_reference",
                "hrms_error_message", "generated_by", "generated_at",
                "hrms_synced_at", "cancelled_by", "cancelled_at",
                "cancellation_reason", "updated_at",
            ], transaction);
            await upsertRows(queryInterface, "payment_batch_item", buildBatchItems(), [
                "payment_batch_id", "payroll_line_id", "staff_id",
                "employee_reference", "employee_name", "bank_code",
                "bank_account_no", "gross_pay", "incentive_pay", "cpf_amount",
                "sdl_amount", "other_deduction", "net_pay", "payment_reference",
                "updated_at",
            ], transaction);
            await upsertRows(queryInterface, "payslip", buildPayslips(), [
                "payment_batch_id", "payroll_line_id", "staff_id",
                "payslip_reference", "company_name", "employee_reference",
                "employee_name", "pay_period_start", "pay_period_end", "gross_pay",
                "incentive_pay", "cpf_amount", "sdl_amount", "other_deduction",
                "net_pay", "batch_reference", "generated_at", "updated_at",
            ], transaction);
            await transaction.commit();
        } catch (error) {
            await transaction.rollback();
            throw error;
        }
    },

    async down(queryInterface) {
        assertDevelopment();
        const transaction = await queryInterface.sequelize.transaction();
        try {
            await removeOwnedData(queryInterface, transaction);
            await transaction.commit();
        } catch (error) {
            await transaction.rollback();
            throw error;
        }
    },
};

